# ------------------------------------------------------------------ ctags
class Tags:
    """qualified name → definitions; class → bases; per-class method ranges."""
    def __init__(self):
        self.classes: dict[str, list] = collections.defaultdict(list)   # qual → [(file, line, end, bases)]
        self.methods: dict[str, list] = collections.defaultdict(list)   # class qual → [(file, line, end, name)]
        self.roots: list[str] = []
        self.short: dict[str, set] = collections.defaultdict(set)         # unqualified class name → quals
        self.file_funcs: dict[str, list] = collections.defaultdict(list)  # file → [(line, end, qualified name)]

    def add(self, tags_path: str):
        if not os.path.exists(tags_path):
            return
        root = os.path.dirname(os.path.abspath(tags_path))
        self.roots.append(root)
        for line in open(tags_path, errors="replace"):
            if line.startswith("!"):
                continue
            parts = line.rstrip("\n").split("\t")
            if len(parts) < 4:
                continue
            name, fpath, pattern, kind = parts[0], parts[1], parts[2], parts[3]
            if "::" in name:      # qualified duplicates (--extras=+q) are handled via scope fields
                continue
            ext = {}
            for e in parts[4:]:
                k, _, v = e.partition(":")
                ext[k] = v
            ln = int(ext.get("line", 0) or 0); end = int(ext.get("end", ln) or ln)
            fabs = os.path.normpath(os.path.join(root, fpath))
            scope = ext.get("class") or ext.get("struct") or ext.get("namespace") or ""
            if kind in ("class", "struct"):
                qual = f"{scope}::{name}" if scope else name
                bases = _bases_from_pattern(pattern)
                self.classes[qual].append((fabs, ln, end, bases))
                self.short[name].add(qual)
            elif kind == "function":
                # definition with a body (line..end)
                cls = ext.get("class") or ext.get("struct")
                if cls:
                    self.methods[cls].append((fabs, ln, end, name))
                self.file_funcs[fabs].append((ln, end, f"{scope}::{name}" if scope else name))

    def resolve_class(self, qual: str):
        if qual in self.classes:
            return qual
        tail = qual.split("::")[-1]
        cands = self.short.get(tail, set())
        if len(cands) == 1:
            return next(iter(cands))
        # prefer same leading namespace
        ns = "::".join(qual.split("::")[:-1])
        for c in cands:
            if ns and c.startswith(ns + "::"):
                return c
        return None


def _bases_from_pattern(pattern: str):
    m = re.search(r":\s*(public|protected|private)?\s*(.+?)\$?/;\"?$", pattern)
    if not m:
        return []
    return [re.sub(r"^(public|protected|private|virtual)\s+", "", b.strip()).strip()
            for b in re.split(r",\s*(?![^<]*>)", m.group(2)) if b.strip()]


def class_bases(tags: Tags, qual: str):
    """bases parsed from the class definition line(s) — the ctags pattern holds only the
    first line; read on until '{' to catch multi-line base lists."""
    out = []
    for fabs, ln, end, bases in tags.classes.get(qual, []):
        try:
            lines = open(fabs, errors="replace").read().splitlines()
        except Exception:
            continue
        buf = ""
        for i in range(ln - 1, min(ln + 8, len(lines))):
            buf += " " + lines[i]
            if "{" in lines[i]:
                break
        head = buf.split("{", 1)[0]
        if ":" in head:
            bl = head.split(":", 1)[1]
            bl = re.sub(r"<[^<>]*>", "", bl)
            for b in bl.split(","):
                b = re.sub(r"\b(public|protected|private|virtual)\b", "", b).strip()
                if b:
                    out.append(b)
        if out:
            break
        out = list(bases)
    return out

# ------------------------------------------------------------------ scanning
_FILE_CACHE: dict[str, list] = {}
_PKG_CACHE: dict[str, tuple] = {}


def source_package(path):
    """(package name, package dir) = nearest ancestor directory holding package.xml."""
    d = os.path.dirname(os.path.abspath(path)); seen = []
    while d and d != "/":
        if d in _PKG_CACHE:
            r = _PKG_CACHE[d]; break
        seen.append(d)
        px = os.path.join(d, "package.xml")
        if os.path.exists(px):
            m = re.search(r"<name>\s*([^<\s]+)\s*</name>", open(px, errors="replace").read())
            r = (m.group(1) if m else os.path.basename(d), d); break
        d = os.path.dirname(d)
    else:
        r = (None, None)
    for x in seen:
        _PKG_CACHE[x] = r
    return r


def _lines(fabs):
    if fabs not in _FILE_CACHE:
        try:
            _FILE_CACHE[fabs] = open(fabs, errors="replace").read().splitlines()
        except Exception:
            _FILE_CACHE[fabs] = []
    return _FILE_CACHE[fabs]


def scan_ranges(ranges, tags_roots, skip=None):
    """ranges: [(file, line, end, method)] → rows [{file, line, code, vcc, delta, method, ctx}].
    A statement that continues over several lines (no ';' yet) is joined (≤6 lines) so that
    `PollingSubscriber<T> sub_{\n this, "topic"}` member initialisers are seen as one.
    skip: set of (file, line) already reported (dedupe across class body / method / file scans)."""
    rows = []
    skip = skip if skip is not None else set()
    for fabs, ln, end, meth in sorted(set(ranges)):
        lines = _lines(fabs)
        i = ln - 1
        while i < min(end, len(lines)):
            raw = lines[i]
            code = raw.strip()
            if not code or code in ("{", "}", "};") or code.startswith(("//", "*", "#", "/*")) or (fabs, i + 1) in skip:
                i += 1; continue
            stmt = raw; j = i
            def _open(st):
                st = st.rstrip()
                if ";" in st or st.endswith("}"):
                    return False
                if st.endswith("{"):
                    return bool(re.search(r"[\w>]\{$", st))      # `name_{` brace-initialiser continues; `) {` / `else {` is a block
                return True
            while _open(stmt) and j - i < 5 and j + 1 < len(lines):
                j += 1; stmt += " " + lines[j].strip()
            matched = []
            for c, rx, d, desc in VCC_RE:
                if rx.search(stmt):
                    matched.append((c, d, desc))
            if matched:
                codes = {m[0] for m in matched}
                for c in list(codes):
                    for loser in EXCLUSIVE.get(c, ()):
                        codes.discard(loser)
                # one row per distinct surviving code on the line
                seen = set()
                for c, d, desc in matched:
                    if c not in codes or c in seen:
                        continue
                    seen.add(c)
                    ctx = ""
                    for q in range(i - 1, max(ln - 2, i - 8), -1):
                        if q < 0:
                            break
                        if CTRL_RE.search(lines[q]) and len(lines[q]) - len(lines[q].lstrip()) < len(raw) - len(raw.lstrip()):
                            ctx = lines[q].strip()[:200]; break
                    if CTRL_RE.search(raw):
                        ctx = "same line: " + code[:200]
                    rel = fabs
                    for r in tags_roots:
                        if fabs.startswith(r + "/"):
                            rel = fabs[len(r) + 1:]; break
                    rows.append({"file": rel, "line": i + 1, "code": (code if ";" in raw else " ".join(x.strip() for x in lines[i:j + 1]))[:220],
                                 "vcc": c, "delta": list(d), "method": meth, "ctx": ctx, "desc": desc})
                for k in range(i, j + 1):
                    skip.add((fabs, k + 1))
                # a joined statement was consumed as a whole: do not re-match its continuation lines
                i = j + 1
                continue
            i += 1
    return rows

# ------------------------------------------------------------------ resolvers (task: exact counts)
def _literal_list_len(text: str, start: int):
    """text[start] == '{' : number of top-level comma-separated items inside the braces."""
    depth = 0; items = 0; seen_item = False; i = start; in_str = False
    while i < len(text):
        ch = text[i]
        if in_str:
            if ch == '\\':
                i += 1
            elif ch == '"':
                in_str = False
        elif ch == '"':
            in_str = True; seen_item = True
        elif ch in "{([":
            depth += 1
            if depth >= 2:
                seen_item = True
        elif ch in "})]":
            depth -= 1
            if depth == 0:
                return items + (1 if seen_item else 0)
        elif ch == "," and depth == 1:
            items += 1; seen_item = False
        elif not ch.isspace() and depth == 1:
            seen_item = True
        i += 1
    return None


def _yaml_find(obj, key):
    """first value of `key` anywhere under obj (ros__parameters trees are nested)."""
    if isinstance(obj, dict):
        if key in obj:
            return obj[key]
        for v in obj.values():
            r = _yaml_find(v, key)
            if r is not None:
                return r
    elif isinstance(obj, list):
        for v in obj:
            r = _yaml_find(v, key)
            if r is not None:
                return r
    return None


def _param_yaml_candidates(launch_params, pkg, install="/opt/autoware"):
    out = [x for x in launch_params if os.path.exists(x)]
    short = (pkg or "").replace("autoware_", "")
    for root in (os.path.join(install, "share", "autoware_launch", "config"), os.path.join(install, "share", pkg or "-", "config")):
        for f in glob.glob(os.path.join(root, "**", "*.yaml"), recursive=True):
            if short and short in os.path.basename(f) and f not in out:
                out.append(f)
    return out


def resolve_loop_multiplicity(row, files, launch_params, pkg):
    """N for a creation call inside a loop: the loop header names a container X; X is resolved to
    (a) a literal initialiser list in the class files, (b) a declare_parameter/get_parameter binding
    whose value is read from the node's parameter yaml, (c) a helper-function parameter bound at the
    call site (one hop). Returns (N, how) or (None, why)."""
    m = re.search(r"for\s*\(.*?:\s*([A-Za-z_][\w.\->]*)\s*\)", row.get("ctx", "")) or \
        re.search(r"<\s*([A-Za-z_][\w.\->]*)\.size\(\)", row.get("ctx", ""))
    if not m:
        return None, "loop container not recognised in header"
    x = m.group(1).split(".")[-1].split("->")[-1]
    texts = {f: "\n".join(_lines(f)) for f in files}
    tried = [x]
    for hop in range(2):
        for f, t in texts.items():
            mm = re.search(r"\b" + re.escape(x) + r"\s*(?:=\s*)?\{", t)             # literal list
            if mm and "declare_parameter" not in t[max(0, mm.start() - 80):mm.start()]:
                n = _literal_list_len(t, t.index("{", mm.start()))
                if n:
                    return n, f"literal list `{x}` ({os.path.basename(f)}:{t[:mm.start()].count(chr(10)) + 1}) = {n} items"
            mm = re.search(r"\b" + re.escape(x) + r"\s*=\s*(?:this->)?declare_parameter\s*<[^;]*?>\s*\(\s*\"([\w.]+)\"", t) or \
                 re.search(r"declare_parameter\s*(?:<[^>]*>)?\s*\(\s*\"([\w.]+)\"\s*,\s*" + re.escape(x) + r"\b", t) or \
                 re.search(r"get_parameter\s*\(\s*\"([\w.]+)\"\s*,\s*" + re.escape(x) + r"\b", t)
            if mm:
                pname = mm.group(1)
                for y in _param_yaml_candidates(launch_params, pkg):
                    try:
                        import yaml
                        val = _yaml_find(yaml.safe_load(open(y)), pname.split(".")[-1])
                    except Exception:
                        val = None
                    if isinstance(val, list):
                        return len(val), f"parameter `{pname}` = {len(val)} items ({y})"
                return None, f"parameter `{pname}` bound to `{x}` but no yaml value found ({len(_param_yaml_candidates(launch_params, pkg))} files tried)"
        # helper-function parameter → call-site argument (one hop)
        fn = row.get("method", "")
        bound = None
        for f, t in texts.items():
            sig = re.search(r"\b" + re.escape(fn.split("::")[-1]) + r"\s*\(([^)]*)\)\s*\{", t)
            if not sig:
                continue
            params = [pp.strip().split()[-1].lstrip("&*") for pp in sig.group(1).split(",") if pp.strip()]
            if x in params:
                idx = params.index(x)
                for f2, t2 in texts.items():
                    for call in re.finditer(r"\b" + re.escape(fn.split("::")[-1]) + r"\s*(?:<[^>]*>)?\s*\(([^;]*)\)\s*;", t2):
                        args = [aa.strip() for aa in call.group(1).split(",")]
                        if idx < len(args) and re.match(r"^[A-Za-z_]\w*$", args[idx]):
                            bound = args[idx]; break
                    if bound:
                        break
            if bound:
                break
        if not bound:
            return None, f"`{x}` not resolvable (tried {', '.join(tried)})"
        tried.append(bound); x = bound
    return None, f"`{x}` not resolvable after 2 hops ({', '.join(tried)})"


_NAME_RE = re.compile(r'"((?:~/|/)?[A-Za-z0-9_][\w/.\-]*)"')


def literal_name(code: str):
    """first quoted topic/service-like literal in a creation call ("~/input/x", "/tf", "input/engage")."""
    for m in _NAME_RE.finditer(code):
        v = m.group(1)
        if v.count("/") == 0 and (v[:1].isupper() or "::" in v or v.endswith((".yaml", ".param"))):
            continue
        return v
    return None


def resolve_if_rows_by_params(rows, files, launch_params, pkg):
    """`if (flag)` / `if (!flag)` / `if (param_.x)` rows still unresolved: bind the condition
    identifier to a declare_parameter<bool>("name") in the class files and read the value from the
    node's parameter yaml; an `else` row in the same method takes the opposite decision."""
    texts = {f: "\n".join(_lines(f)) for f in files}
    ylist = None
    def param_value(pname):
        nonlocal ylist
        if ylist is None:
            ylist = _param_yaml_candidates(launch_params, pkg)
        for y in ylist:
            try:
                import yaml
                v = _yaml_find(yaml.safe_load(open(y)), pname.split(".")[-1])
            except Exception:
                v = None
            if v is not None:
                return v, y
        return None, None
    last_if = {}
    for r in rows:
        ctx = r.get("ctx", "")
        if r.get("resolved") or r.get("deferred") or not (r["delta"][0] or r["delta"][1]):
            continue
        m = re.match(r"if\s*\(\s*(!?)\s*([A-Za-z_][\w.\->]*)\s*\)", ctx)
        if m:
            neg, ident = m.group(1) == "!", m.group(2).split(".")[-1].split("->")[-1]
            pname = None; default = None
            for f, t in texts.items():
                mm = re.search(r"\b" + re.escape(ident) + r"\s*=\s*[^;]*?declare_parameter\s*(?:<[^>]*>)?\s*\(\s*\"([\w.]+)\"(?:\s*,\s*(true|false))?", t) or \
                     re.search(r"declare_parameter\s*(?:<[^>]*>)?\s*\(\s*\"([\w.]+)\"\s*,\s*" + re.escape(ident) + r"\b()", t) or \
                     re.search(r"get_parameter\s*\(\s*\"([\w.]+)\"\s*,\s*" + re.escape(ident) + r"\b()", t) or \
                     re.search(r"\b" + re.escape(ident) + r"\s*=\s*[^;]*get_parameter\s*\(\s*\"([\w.]+)\"()", t)
                if mm:
                    pname = mm.group(1); default = mm.group(2) if mm.lastindex and mm.lastindex >= 2 else None; break
            if not pname:
                continue
            val, src = param_value(pname)
            if val is None and default in ("true", "false"):
                val, src = (default == "true"), "code default"
            if isinstance(val, bool):
                taken = (not val) if neg else val
                r["resolved"] = "created" if taken else "absent"
                r["ctx"] += f"; resolved by parameter `{pname}`={val} ({os.path.basename(src) if src else '?'})"
                last_if[r.get("method")] = taken
        elif re.match(r"(\}\s*)?else\b", ctx) and r.get("method") in last_if:
            taken = not last_if[r["method"]]
            r["resolved"] = "created" if taken else "absent"
            r["ctx"] += "; resolved as the else-branch of the parameter-resolved if"


def resolve_rows_by_names(rows, counted_labels, remaps=None, remaps_known=False):
    """deferred / if-guarded rows: decide created|absent by matching the row's literal name (after the
    launch remappings) against the counted E labels of the node (static rows claim first).
    'absent' is only concluded when the node's remap table is known (composable nodes from
    launch_components); for executables an unmatched literal stays unresolved (range logic)."""
    counted = collections.Counter(l.rsplit("/", 1)[-1] for l in counted_labels)
    remaps = remaps or {}
    def claim(r):
        nm = literal_name(r["code"])
        if not nm:
            return None
        key = nm[2:] if nm.startswith("~/") else nm
        tgt = remaps.get(key) or remaps.get(nm) or remaps.get("/" + key) or nm
        b = tgt.rstrip("/").rsplit("/", 1)[-1]
        if counted.get(b, 0) > 0:
            counted[b] -= 1; return "created"
        return "absent" if remaps_known else None
    for r in rows:
        if not r.get("deferred") and not re.match(r"(if|else|switch|case|\?|same line)", r.get("ctx", "")) and (r["delta"][0]):
            claim(r)                                                # static rows consume their names silently
    for r in rows:
        if (r.get("deferred") or re.match(r"(if|else|switch|case|\?|same line)", r.get("ctx", ""))) and (r["delta"][0] or r["delta"][1]):
            res = claim(r)
            if res:
                r["resolved"] = res
                r["ctx"] = r["ctx"] + f"; resolved by counted names: {res}"

# ------------------------------------------------------------------ node → class
def load_launch_components(session_dir):
    """launch_components.json → composable {name → set(plugin)}, executables {full_name → (pkg, exe)}"""
    p = os.path.join(session_dir, "launch_components.json")
    comp = collections.defaultdict(set); exe = {}
    if not os.path.exists(p):
        return comp, exe
    d = json.load(open(p))
    for cont, v in d.items():
        for c in v:
            if not isinstance(c, dict):
                continue
            nm = c.get("name")
            if isinstance(nm, list):               # unresolved launch substitution: keep the literal prefix
                nm = "".join(x for x in nm if isinstance(x, str))
                if nm and "plugin" in c:
                    comp["~prefix:" + nm].add((cont, c.get("namespace"), c["plugin"], c.get("package"), tuple(x for x in (c.get("parameters") or []) if isinstance(x, str)),
                                               tuple((str(a_), str(b_)) for a_, b_ in (c.get("remappings") or []) if isinstance(a_, str) and isinstance(b_, str))))
                continue
            if not isinstance(nm, str):
                continue
            if "plugin" in c:
                comp[nm].add((cont, c.get("namespace"), c["plugin"], c.get("package"), tuple(x for x in (c.get("parameters") or []) if isinstance(x, str)),
                              tuple((str(a_), str(b_)) for a_, b_ in (c.get("remappings") or []) if isinstance(a_, str) and isinstance(b_, str))))
            else:
                exe[nm] = (c.get("package"), c.get("executable"))
    return comp, exe


def cmake_index(src_roots):
    """package → {exe → plugin class} from rclcpp_components_register_node(... PLUGIN "x" EXECUTABLE y)
    and {exe → [source files]} from add_executable/ament_auto_add_executable."""
    reg = collections.defaultdict(dict); exes = collections.defaultdict(dict); pkg_of = {}
    for sr in src_roots:
        for cm in glob.glob(os.path.join(sr, "**", "CMakeLists.txt"), recursive=True):
            d = os.path.dirname(cm)
            px = os.path.join(d, "package.xml")
            if not os.path.exists(px):
                continue
            try:
                pkg = re.search(r"<name>\s*([^<\s]+)", open(px).read()).group(1)
                txt = open(cm, errors="replace").read()
            except Exception:
                continue
            pkg_of[pkg] = d
            for m in re.finditer(r"rclcpp_components_register_node(?:s)?\s*\(([^)]*)\)", txt, re.S):
                body = m.group(1)
                pl = re.search(r'PLUGIN\s+"([^"]+)"', body); ex = re.search(r"EXECUTABLE\s+(\S+)", body)
                if pl and ex:
                    reg[pkg][ex.group(1).replace("${PROJECT_NAME}", pkg)] = pl.group(1)
            for m in re.finditer(r"(?:ament_auto_add_executable|add_executable)\s*\(\s*(\S+)([^)]*)\)", txt, re.S):
                exes[pkg][m.group(1)] = [s for s in m.group(2).split() if re.search(r"\.(cpp|cc|cu)$", s)]
    return reg, exes, pkg_of


def class_from_symbols(symbols, tags=None):
    """majority C++ class among callback symbols registered for the node (rclcpp infra excluded);
    when a ctags index is given, a class that derives from rclcpp::Node wins over helper classes
    (e.g. PoseInitializer over its GnssModule whose callbacks are more numerous)."""
    cnt = collections.Counter()
    for s in symbols:
        q = None
        m = re.match(r"std::_Bind<[^(]*\(((?:[A-Za-z_]\w*::)+)\*", s)          # member-function pointer type → class
        if m:
            q = m.group(1).rstrip(":")
        else:
            head = s.split("::{lambda", 1)[0]                                   # lambda inside Class::method(...)
            head = re.sub(r"<[^<>]*>", "", re.sub(r"<[^<>]*>", "", head))        # strip (nested) template args
            head = head.split("(", 1)[0]
            parts = head.split("::")
            if len(parts) >= 3:
                q = "::".join(parts[:-1])
        if not q:
            continue
        if q.startswith(("rclcpp", "std", "tf2_ros", "rclcpp_components", "diagnostic_updater", "message_filters",
                         "autoware_utils", "autoware::universe_utils", "perception_utils", "negotiated", "rclcpp_lifecycle")):
            continue
        cnt[q] += 1
    if not cnt:
        return None
    if tags is not None:
        for q, _n in cnt.most_common():
            rq = tags.resolve_class(q)
            if rq and any(re.search(r"rclcpp::Node\b|LifecycleNode\b", b) for b in class_bases(tags, rq)):
                return q
    return cnt.most_common(1)[0][0]

# ------------------------------------------------------------------ actual
def summarize_graph(path):
    d = json.load(open(path))
    by_id = {n["id"]: n for n in d["nodes"]}
    pid_of_n = {}
    for ex in d["nodes"]:
        if ex.get("type") == "EX":
            for c in ex.get("children", []):
                pid_of_n[c] = ex.get("pid")
    out = {}
    for n in d["nodes"]:
        if n.get("type") != "N":
            continue
        full = n.get("full_name") or n.get("label")
        e = out.setdefault(full, {"E": 0, "F": 0, "pid": n.get("pid") if n.get("pid") is not None else pid_of_n.get(n["id"]), "sub": [], "serv": [], "tmr": [],
                                  "waitable": [], "other": [], "pub": set(), "cli": set(), "symbols": []})
        for cid in n.get("children", []):
            c = by_id.get(cid)
            if not c or c.get("type") != "E":
                continue
            e["E"] += 1
            et = c.get("etype"); lab = c.get("label", "?")
            {"sub": e["sub"], "serv": e["serv"], "tmr": e["tmr"], "waitable": e["waitable"]}.get(et, e["other"]).append(
                str(c.get("period_ns", lab)) if et == "tmr" else lab)
            for a in c.get("aspects") or []:
                if a.get("aspect") == "pub" and et not in ("serv", "cli"):
                    e["pub"].add(a.get("topic") or a.get("service") or "?")
            for fid in c.get("children", []):
                f = by_id.get(fid)
                if f and f.get("type") == "F":
                    if f.get("split") == "response":
                        e.setdefault("split_F", 0); e["split_F"] = e.get("split_F", 0) + 1
                        continue                       # `::continuation` F added by split_callbacks (client-bearing callbacks) — not a registered callback
                    e["F"] += 1; e["symbols"].append(f.get("label", ""))
                    for a in f.get("aspects") or []:
                        if a.get("aspect") == "pub":
                            e["pub"].add(a.get("topic") or "?")
                        elif a.get("aspect") == "cli":
                            e["cli"].add(a.get("service") or "?")
        for k in ("pub", "cli"):
            pass
    for e in out.values():
        e["pub"] = sorted(e["pub"]); e["cli"] = sorted(e["cli"])
    return out

# ------------------------------------------------------------------ main
def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("session_dir"); ap.add_argument("graph_json")
    ap.add_argument("--prov", default="/opt/fish_provenance")
    ap.add_argument("--prov-extra", action="append", default=["/opt/fish_provenance_ros"])
    ap.add_argument("--out", default=None)
    ap.add_argument("--overlay-ws", default="/root/trace_overlay_ws",
                    help="FISH overlay workspace; its fish_rebuilt_packages.json lists prebuilt packages recompiled against the overlay headers")
    ap.add_argument("--sim-time", choices=["auto", "yes", "no"], default="auto",
                    help="use_sim_time → every rclcpp node gets a /clock sub (TimeSource); auto = majority of counted nodes")
    a = ap.parse_args(argv)
    t0 = time.time()
    log = lambda *x: print("[aw-a2]", *x, flush=True)
    roots = [a.prov] + [x for x in a.prov_extra if os.path.isdir(x)]
    tags = Tags()
    for r in roots:
        tags.add(os.path.join(r, "tags"))
    log(f"tags: {len(tags.classes)} classes, {sum(len(v) for v in tags.methods.values())} method bodies from {roots}")
    src_roots = [os.path.join(r, "src") for r in roots]
    reg, exes, pkg_of = cmake_index(src_roots)
    log(f"cmake: {sum(len(v) for v in reg.values())} registered component executables, {sum(len(v) for v in exes.values())} plain executables")
    rebuilt = set()
    try:
        rebuilt = set(json.load(open(os.path.join(a.overlay_ws, "fish_rebuilt_packages.json"))).get("rebuilt", {}))
    except Exception:
        pass
    log(f"packages rebuilt against the overlay (header-level tracepoints reach them): {sorted(rebuilt) or 'none'}")
    comp, exe_nodes = load_launch_components(a.session_dir)
    pid_exe = {}; pid_libs = {}
    try:
        pk = json.load(open(os.path.join(a.session_dir, "provenance", "packages.json")))
        pid_exe = {int(pid): pr.get("exe") for pid, pr in pk.get("processes", {}).items() if pr.get("exe")}
        pid_libs = {int(pid): set(pr.get("libs", [])) for pid, pr in pk.get("processes", {}).items()}
    except Exception:
        pass
    lib2classes = collections.defaultdict(list)          # installed component lib → plugin classes (ament index)
    for root in ("/opt/autoware", "/opt/ros/humble"):
        for f in glob.glob(os.path.join(root, "share", "ament_index", "resource_index", "rclcpp_components", "*")):
            for line in open(f, errors="replace"):
                if ";" in line:
                    cls_, lib = line.strip().split(";", 1)
                    lib2classes[os.path.normpath(os.path.join(root, lib))].append(cls_)

    def class_from_container_libs(pid, bn):
        """composable node not in launch_components: candidate plugin classes = component libs mapped in the
        container process; pick the one whose package/class tokens overlap the node name best."""
        cands = [c for lib in pid_libs.get(pid, ()) for c in lib2classes.get(os.path.normpath(lib), [])]
        if not cands:
            return None, 0
        toks = set(re.split(r"[_/]", bn.lower())) - {""}
        best, score = None, 0
        for c in set(cands):
            ct = set(re.split(r"[_:]", re.sub(r"([a-z])([A-Z])", r"\1_\2", c).lower())) - {"", "autoware", "node", "component"}
            sc = len(toks & ct)
            if sc > score:
                best, score = c, sc
        return best, score
    actual = summarize_graph(a.graph_json)
    log(f"graph: {len(actual)} N vertices; launch: {len(comp)} composable names, {len(exe_nodes)} executable nodes")

    n_clock = sum(1 for e in actual.values() if "/clock" in e["sub"])
    sim = a.sim_time == "yes" or (a.sim_time == "auto" and n_clock > len(actual) / 2)
    log(f"use_sim_time: {sim} ({n_clock}/{len(actual)} nodes have a /clock sub)")

    def node_kind(full):
        b = full.rsplit("/", 1)[-1]
        if full.startswith("/_ros2cli") or b.startswith("_ros2cli"):
            return "ros2cli"
        if b.startswith("transform_listener_impl"):
            return "tf_helper"
        if b.startswith("managed_tf_listener_impl"):
            return "mtf_helper"
        if b.startswith("launch_ros"):
            return "launch_ros"
        if b.endswith("_container") or b == "container" or full.endswith("container"):
            return "container"
        return "node"

    results = {}
    class_cache = {}
    _text_cache = {}

    def _class_text(rq):
        """all source lines of a class's method bodies (for the pluginlib check)."""
        if not rq:
            return []
        if rq in _text_cache:
            return _text_cache[rq]
        out = []
        for fabs, ln, end, _n in tags.methods.get(rq, []):
            try:
                out += open(fabs, errors="replace").read().splitlines()[ln - 1:end]
            except Exception:
                pass
        _text_cache[rq] = out
        return out

    def class_review(qual, prefer_pkg=None):
        """rows + expected delta for a class incl. its bases (recursive, memoised)."""
        key = (qual, prefer_pkg)
        if key in class_cache:
            return class_cache[key]
        rq = tags.resolve_class(qual)
        info = {"class": qual, "resolved": rq, "bases": [], "rows": [], "files": [], "lifecycle": False, "base_rclcpp": None}
        class_cache[key] = info
        if not rq:
            return info
        ranges = list(tags.methods.get(rq, []))
        cls_defs = list(tags.classes.get(rq, []))
        pkgs = {source_package(f)[0] for f, _l, _e, _b in cls_defs} | {source_package(f)[0] for f, _l, _e, _n in ranges}
        if len(pkgs) > 1:
            installed = {p for p in pkgs if p and os.path.isdir(f"/opt/autoware/share/{p}")}
            keep = prefer_pkg if prefer_pkg in pkgs else (next(iter(installed)) if len(installed) == 1 else None)
            if keep:
                ranges = [r for r in ranges if source_package(r[0])[0] == keep]
                cls_defs = [c for c in cls_defs if source_package(c[0])[0] == keep]
                info["note"] = f"class defined in {len(pkgs)} packages ({', '.join(sorted(p for p in pkgs if p))}); using installed {keep}"
        skip = set()
        rows = []
        for fabs, ln, end, _b in cls_defs:
            info["files"].append(fabs)
        # 1. the class's own method bodies (ctor + others) — first, so that inline methods inside the
        #    class body are attributed to their method (skip set prevents the body pass re-matching them)
        short = rq.split("::")[-1]
        INIT_NAMES = {short, "init", "initialize", "onInit", "on_init", "initializeNode", "init_node", "setup"}
        # methods invoked (directly) from the constructor / init-like methods run at construction → static
        ctor_calls = set()
        for fabs, ln, end, mname in ranges:
            if mname in INIT_NAMES:
                body = "\n".join(_lines(fabs)[ln - 1:end])
                ctor_calls |= set(re.findall(r"(?<![\w.>])([A-Za-z_]\w*)\s*\(", body))
        ctor_calls -= {"if", "for", "while", "switch", "return", "sizeof", "static_cast", "dynamic_cast"}
        for r in scan_ranges(ranges, tags.roots, skip):
            m = r["method"]
            if m in INIT_NAMES:
                pass
            elif m in ctor_calls:
                r["ctx"] = (r["ctx"] + "; " if r["ctx"] else "") + f"in method {m}() called from the constructor"
            else:
                r["ctx"] = (r["ctx"] + "; " if r["ctx"] else "") + f"deferred: created in method {m}() (runs only if called at runtime)"
                r["deferred"] = True
            rows.append(r)
        # 2. class body: member declarations / brace initialisers `Sub<T> sub_{this, "topic"}`, `Updater u_;`
        body = [(fabs, ln, end, "(class body: member declaration)") for fabs, ln, end, _b in cls_defs]
        rows += scan_ranges(body, tags.roots, skip)
        # 3. helpers in the same translation units (free functions / other classes called from the ctor):
        #    everything else in the class's files, attributed to the enclosing function, flagged
        files = sorted({f for f, _l, _e, _n in ranges} | set(info["files"]))
        for fabs in files:
            cls_spans = [(l, e) for f, l, e, _n in ranges if f == fabs] + [(l, e) for f, l, e, _b in cls_defs if f == fabs]
            for l, e, fn in tags.file_funcs.get(fabs, []):
                if any(cl <= l and e <= ce for cl, ce in cls_spans):
                    continue                     # a method of this class (already scanned)
                for r in scan_ranges([(fabs, l, e, fn)], tags.roots, skip):
                    r["ctx"] = (r["ctx"] + "; " if r["ctx"] else "") + f"outside class: in {fn}() of the same file"
                    r["helper"] = True
                    rows.append(r)
        # 4. helper classes constructed WITH the node (`make_shared<X>(*this, …)`, `X(this)`, member
        #    `X m_{this}`) whose sources are in the provenance tree and which are not already covered
        #    by a VCCA rule: their creation rows count for this node (flagged "via helper class X").
        HELPER_SKIP = ("LoggerLevelConfigure", "Updater", "RTCInterface", "VehicleStopChecker", "VehicleArrivalChecker",
                       "WatchdogTimer", "InterProcessPollingSubscriber", "TransformListener", "NodeAdaptor",
                       "DiagnosticsInterface", "PublishedTimePublisher", "DebugPublisher", "ProcessingTimePublisher",
                       "TimeKeeper", "StopWatch", "Buffer", "TransformBroadcaster", "StaticTransformBroadcaster",
                       "ParametersClient", "AsyncParametersClient", "SyncParametersClient", "ManagedTransformBuffer",
                       "PlanningFactorInterface", "LoggingNode")
        inst_re = re.compile(r"(?:make_shared|make_unique|emplace)\s*<?\s*([A-Za-z_][\w:]*)\s*>?\s*\(\s*(?:&?\*?this\b|\*?parent_node\b|node\b|get_node_base|shared_from_this)")
        inst_re2 = re.compile(r"\b([A-Z]\w+)\s+\w+\s*[\{(]\s*(?:\*?this\b|node\b)")
        helpers = collections.Counter()
        body_text = "\n".join(l for f, l0, e0, _b in cls_defs for l in _lines(f)[l0 - 1:e0])
        emplace_re = re.compile(r"\b(\w+)\.emplace\s*\(\s*(?:\*?this\b|node\b)")
        for fabs, ln, end, _n in ranges + [(f, l, e, "(class body)") for f, l, e, _b in cls_defs]:
            text = "\n".join(_lines(fabs)[ln - 1:end])
            found = []
            for mm in list(inst_re.finditer(text)) + list(inst_re2.finditer(text)):
                found.append((mm.group(1), mm.start()))
            for mm in emplace_re.finditer(text):                              # std::optional<X> m_; m_.emplace(this, …)
                md = re.search(r"(?:std::)?(?:optional|unique_ptr|shared_ptr)\s*<\s*([\w:]+)\s*>\s+" + re.escape(mm.group(1)) + r"\b", body_text)
                if md:
                    found.append((md.group(1), mm.start()))
            for hq, off in found:
                cname = hq.split("::")[-1]
                if cname in HELPER_SKIP or cname == short or cname.startswith("std"):
                    continue
                hl = ln + text[:off].count("\n")
                guard = ""
                lines_ = _lines(fabs)
                for q in range(hl - 2, max(ln - 2, hl - 9), -1):
                    if q < 0:
                        break
                    if CTRL_RE.search(lines_[q]) and len(lines_[q]) - len(lines_[q].lstrip()) < len(lines_[hl - 1]) - len(lines_[hl - 1].lstrip()):
                        guard = lines_[q].strip()[:200]; break
                helpers[(hq, os.path.basename(fabs), hl, guard)] += 1
        for (hq, hf, hl, guard), n_inst in helpers.items():
            hrq = tags.resolve_class(hq if "::" in hq else rq.rsplit("::", 1)[0] + "::" + hq) or tags.resolve_class(hq)
            if not hrq or hrq == rq:
                continue
            if source_package(tags.classes[hrq][0][0])[0] != source_package(cls_defs[0][0])[0] if cls_defs and tags.classes.get(hrq) else True:
                continue                                   # only same-package helpers (external ones need an explicit VCCA rule)
            sub = class_review(hrq, prefer_pkg)
            for r in sub["rows"]:
                if r.get("deferred") or r.get("helper"):
                    continue
                rr = dict(r); rr["ctx"] = (guard + "; " if guard else "") + (r["ctx"] + "; " if r["ctx"] else "") + f"via helper class {hq} ({hf}:{hl}, {n_inst}×)"
                rr["helper"] = True; rr["delta"] = [x * n_inst for x in r["delta"]]
                rows.append(rr)
            for b in sub["bases"]:
                pass
        # diagnostic_updater::Updater re-creates its timer when the `diagnostic_updater.period`
        # parameter is overridden (diagnostic_updater.hpp: update_timer_ reset in the parameter
        # callback) → a second timer E/F is possible; modelled as a deferred (runtime) row
        for r in [r for r in rows if r["vcc"] == "VCCA3"]:
            rows.append(dict(r, vcc="VCCA3p", delta=[1, 1, 0, 0], deferred=True,
                             ctx="deferred: Updater timer re-created if diagnostic_updater.period is set by parameter",
                             desc="diagnostic_updater::Updater period override → update_timer_ re-created (second rcl_timer_init)"))
        info["rows"] = rows
        for b in class_bases(tags, rq):
            bq = b.replace("::", "::")
            if re.search(r"\brclcpp::Node\b|\brclcpp_lifecycle::LifecycleNode\b|\bLifecycleNode\b|\brclcpp::Node$", b):
                info["base_rclcpp"] = b
                if "Lifecycle" in b:
                    info["lifecycle"] = True
                continue
            sub = class_review(bq if "::" in bq else (rq.rsplit("::", 1)[0] + "::" + bq), prefer_pkg)
            info["bases"].append(sub)
            if sub.get("base_rclcpp") and not info["base_rclcpp"]:
                info["base_rclcpp"] = sub["base_rclcpp"]
            if sub.get("lifecycle"):
                info["lifecycle"] = True
        return info

    def flatten_rows(info, acc, seen):
        if id(info) in seen:
            return
        seen.add(id(info))
        for r in info["rows"]:
            acc.append(dict(r, cls=info["resolved"] or info["class"]))
        for b in info["bases"]:
            flatten_rows(b, acc, seen)

    for full, act in sorted(actual.items()):
        kind = node_kind(full)
        rec = {"full_name": full, "kind": kind, "pid": act["pid"], "class": None, "class_how": None,
               "rows": [], "expected": None, "actual": {"E": act["E"], "F": act["F"], "pub": len(act["pub"]), "cli": len(act["cli"]),
                                                          "sub": act["sub"], "serv": act["serv"], "tmr": act["tmr"], "waitable": act["waitable"],
                                                          "other": act["other"], "pub_topics": act["pub"], "cli_names": act["cli"]},
               "notes": []}
        base = None
        launch_pkg = None; launch_params = []; launch_remaps = {}; remaps_known = False
        if kind == "ros2cli":
            rec["notes"].append("runtime CLI helper — excluded from the static model")
        elif kind == "launch_ros":
            base = VCC1_RCLPY; rec["class"] = "launch_ros (rclpy)"; rec["class_how"] = "name"
        elif kind == "tf_helper":
            base = TF_HELPER; rec["class"] = "tf2_ros::TransformListener helper node"; rec["class_how"] = "name (transform_listener.cpp:52-56)"
        elif kind == "mtf_helper":
            base = TF_HELPER; rec["class"] = "managed_transform_buffer provider node"; rec["class_how"] = "name (managed_transform_buffer_provider.cpp:101-133)"
        elif kind == "container":
            base = tuple(x + y for x, y in zip(VCC1_CM, CONTAINER_SVCS)); rec["class"] = "rclcpp_components::ComponentManager"; rec["class_how"] = "name"
        else:
            bn = full.rsplit("/", 1)[-1]
            cls = None
            cands = comp.get(bn)
            if not cands:
                pref = [(k, v) for k, v in comp.items() if k.startswith("~prefix:") and bn.startswith(k[8:])]
                if pref:
                    cands = set().union(*[v for _k, v in pref]); rec["notes"].append("name matched by launch-substitution prefix " + pref[0][0][8:])
            if cands:
                plugins = {c[2] for c in cands}
                launch_pkg = next(iter({c[3] for c in cands if c[3]}), None)
                launch_params = sorted({y for c in cands for y in (c[4] if len(c) > 4 else ())})
                launch_remaps = {a_: b_ for c in cands for a_, b_ in (c[5] if len(c) > 5 else ())}; remaps_known = True
                if len(plugins) == 1:
                    cls = next(iter(plugins)); rec["class_how"] = "launch_components plugin"
                else:
                    sym_cls = class_from_symbols(act["symbols"], tags)
                    for p in plugins:
                        if sym_cls and (p.startswith(sym_cls) or sym_cls.startswith(p)):
                            cls = p; rec["class_how"] = "launch_components plugin (disambiguated by symbols)"; break
                    if not cls:
                        cls = sorted(plugins)[0]; rec["class_how"] = f"launch_components plugin (AMBIGUOUS among {len(plugins)})"
                        rec["notes"].append("ambiguous plugin: " + ", ".join(sorted(plugins)))
            if not cls and bn in exe_nodes:
                pkg, exe = exe_nodes[bn]
                if exe in reg.get(pkg, {}):
                    cls = reg[pkg][exe]; rec["class_how"] = f"cmake register_node {pkg}/{exe}"
                else:
                    sym_cls = class_from_symbols(act["symbols"], tags)
                    if sym_cls:
                        cls = sym_cls; rec["class_how"] = f"symbols majority ({pkg}/{exe})"
            if not cls:
                sym_cls = class_from_symbols(act["symbols"], tags)
                if sym_cls:
                    cls = sym_cls; rec["class_how"] = "symbols majority"
            if not cls and act.get("pid") in pid_exe:
                exe_path = pid_exe[act["pid"]]
                m = re.search(r"/lib/([^/]+)/([^/]+)$", exe_path)
                if m and m.group(2) in reg.get(m.group(1), {}):
                    cls = reg[m.group(1)][m.group(2)]; rec["class_how"] = f"process exe → cmake register_node {m.group(1)}/{m.group(2)}"
                elif "component_container" in exe_path:
                    c2, sc = class_from_container_libs(act["pid"], bn)
                    if c2 and sc >= 2:
                        cls = c2; rec["class_how"] = f"container's mapped component libs (name-token match {sc})"
            rec["class"] = cls
            if cls:
                info = class_review(cls, launch_pkg)
                rec["class_resolved"] = info["resolved"]
                if info.get("note"):
                    rec["notes"].append(info["note"])
                if not info["resolved"]:
                    rec["notes"].append("class not found in ctags index (no sources) — expected = VCC1 baseline only")
                acc = []; flatten_rows(info, acc, set())
                for r in acc:
                    if r["vcc"] == "VCC_GS":
                        pkg = source_package(os.path.join(a.prov, r["file"]) if not os.path.isabs(r["file"]) else r["file"])[0]
                        for root in roots:
                            if os.path.exists(os.path.join(root, r["file"])):
                                pkg = source_package(os.path.join(root, r["file"]))[0]; break
                        if pkg not in rebuilt:
                            r["delta"] = [1, 0, 0, 0]
                            r["ctx"] = (r["ctx"] + "; " if r["ctx"] else "") + f"prebuilt {pkg}: GenericSubscription header tracepoints not compiled in → E only, no F"
                rec["rows"] = acc
                rec["base_rclcpp"] = info.get("base_rclcpp")
                rec["lifecycle"] = info.get("lifecycle", False)
                base = VCC1_RCLCPP
                if info.get("lifecycle"):
                    base = tuple(x + y for x, y in zip(base, LIFECYCLE_EXTRA))
            else:
                rec["notes"].append("no class identified — expected = VCC1 baseline only")
                base = VCC1_RCLCPP
        if base is not None:
            E, F, P = base
            if sim and kind != "launch_ros":
                E += CLOCK_SUB[0]; F += CLOCK_SUB[1]
            # ---- resolution step (exact counts where the sources / parameters / counted names allow it)
            counted_labels = list(act["sub"]) + list(act["serv"])
            cls_files = []
            if rec.get("class_resolved"):
                info = class_cache.get((rec["class"], launch_pkg)) or {}
                cls_files = sorted({f for f, _l, _e, _n in tags.methods.get(rec["class_resolved"], [])} | set(info.get("files", [])))
            for r in rec["rows"]:
                if re.match(r"(for|while)", r.get("ctx", "")) and (r["delta"][0] or r["delta"][1]) and not r.get("deferred"):
                    src_pkg = source_package(cls_files[0])[0] if cls_files else None
                    n, how = resolve_loop_multiplicity(r, cls_files, launch_params if kind == "node" else [], src_pkg or launch_pkg)
                    if n:
                        r["mult"] = n; r["ctx"] = r["ctx"] + f"; loop × {n}: {how}"
                    else:
                        r["ctx"] = r["ctx"] + f"; loop multiplicity unresolved: {how}"
            resolve_rows_by_names(rec["rows"], counted_labels, launch_remaps, remaps_known)
            resolve_if_rows_by_params(rec["rows"], cls_files, launch_params if kind == "node" else [],
                                      (source_package(cls_files[0])[0] if cls_files else None) or launch_pkg)
            # ---- sums: static (resolved) part + unresolved range part
            C = 0; dfE = dfF = 0; ifE = ifF = 0; loop_open = False
            for r in rec["rows"]:
                dE, dF, dP, dC = r["delta"]
                is_if = bool(re.match(r"(if|else|switch|case|\?|same line)", r.get("ctx", ""))) and not r.get("deferred")
                if r.get("mult"):
                    E += dE * r["mult"]; F += dF * r["mult"]; P += dP * r["mult"]; C += dC * r["mult"]; continue
                if r.get("deferred"):
                    if r.get("resolved") == "created":
                        E += dE; F += dF; P += dP; C += dC
                    elif r.get("resolved") == "absent":
                        pass
                    else:
                        dfE += dE; dfF += dF                            # unresolved deferred → range upper bound
                    continue
                if is_if and r.get("resolved") == "absent":
                    continue
                if is_if and not r.get("resolved"):
                    ifE += dE; ifF += dF                                # unresolved if-guarded → range lower bound
                if re.match(r"(for|while)", r.get("ctx", "")) and not r.get("mult") and (dE or dF):
                    loop_open = True
                E += dE; F += dF; P += dP; C += dC
            n_oore = len(act["other"])            # GPU (oore) threads are runtime entities outside the static model
            aE = act["E"] - n_oore; aF = act["F"] - n_oore
            rec["expected"] = {"E": E, "F": F, "pub": P, "cli": C, "deferred_E": dfE, "deferred_F": dfF,
                               "base": list(base), "clock": bool(sim and kind != "launch_ros"),
                               "resolved": {"loops": sum(1 for r in rec["rows"] if r.get("mult")),
                                            "created": sum(1 for r in rec["rows"] if r.get("resolved") == "created"),
                                            "absent": sum(1 for r in rec["rows"] if r.get("resolved") == "absent")}}
            rec["actual"]["oore"] = n_oore
            rec["launch_remaps"] = launch_remaps; rec["remaps_known"] = remaps_known
            rec["delta"] = {"E": aE - E, "F": aF - F}
            lo_E, lo_F = E - ifE, F - ifF
            hi_E, hi_F = E + dfE, F + dfF
            rtc = any(("cooperate_commands" in x or "/rtc/" in x or x.endswith("/auto_mode")) for x in act["serv"])
            rec["expected"]["range"] = [lo_E, "inf" if loop_open else hi_E]
            if rec["delta"]["E"] == 0 and rec["delta"]["F"] == 0:
                rec["verdict"] = "OK"
            elif lo_E <= aE <= (10**9 if loop_open else hi_E) and lo_F <= aF <= (10**9 if loop_open else hi_F) and (aE - lo_E) == (aF - lo_F):
                why = []
                if ifE and aE < E: why.append(f"{E - aE} unresolved if-guarded row(s) not taken")
                if dfE and aE > E: why.append("unresolved deferred row(s) created at runtime")
                if loop_open and aE > E: why.append(f"unresolved loop row(s) (+{aE - E})")
                rec["verdict"] = "OK:range"; rec["notes"].append("within static range: " + "; ".join(why))
            elif rtc and not any(r["vcc"] == "VCCA4" for r in rec["rows"]):
                rec["verdict"] = "mismatch:plugins"; rec["notes"].append("RTC/auto_mode services come from scene-module plugins (pluginlib) — not in this class's sources")
            else:
                ctx_rows = [r for r in rec["rows"] if r.get("ctx") and not r.get("mult") and not r.get("resolved") and (r["delta"][0] or r["delta"][1])]
                plugin = any(re.search(r"pluginlib|ClassLoader|createSharedInstance|load_plugin|createUnmanagedInstance", r["code"]) for r in rec["rows"]) \
                    or any(re.search(r"pluginlib|ClassLoader", l) for l in _class_text(rec.get("class_resolved")))
                if plugin:
                    rec["verdict"] = "mismatch:plugins"      # scene modules / filters loaded via pluginlib create their own entities
                elif ctx_rows:
                    rec["verdict"] = "mismatch:ctx"          # loop/if-conditioned creation rows that could not be resolved
                else:
                    rec["verdict"] = "mismatch"
        results[full] = rec

    modelled = [r for r in results.values() if r.get("expected")]
    ok = sum(1 for r in modelled if r["verdict"] == "OK")
    log("verdicts: " + ", ".join(f"{k}={v}" for k, v in collections.Counter(r["verdict"] for r in modelled).most_common()))
    tE = sum(r["expected"]["E"] for r in modelled); tF = sum(r["expected"]["F"] for r in modelled)
    aE = sum(r["actual"]["E"] for r in modelled); aF = sum(r["actual"]["F"] for r in modelled)
    log(f"modelled {len(modelled)} nodes: OK {ok}, mismatch {len(modelled)-ok}; expected E/F {tE}/{tF} vs counted {aE}/{aF}")
    by_how = collections.Counter(r.get("class_how") for r in modelled)
    log("class identification: " + ", ".join(f"{k}={v}" for k, v in by_how.most_common()))
    out = a.out or os.path.join(a.session_dir, "provenance", "a2_expected.json")
    os.makedirs(os.path.dirname(out), exist_ok=True)
    json.dump({"session": os.path.basename(a.session_dir.rstrip("/")), "graph_json": a.graph_json, "use_sim_time": sim,
               "roots": roots, "vcc": [(c, rx, list(d), desc) for c, rx, d, desc in VCC],
               "summary": {"modelled": len(modelled), "ok": ok, "expected_E": tE, "expected_F": tF, "actual_E": aE, "actual_F": aF},
               "nodes": results}, open(out, "w"), indent=1, default=list)
    log(f"done in {time.time()-t0:.0f} s → {out}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
